package main

import (
	"bufio"
	"fmt"
	"os"
	"sort"
)

func gao1(a, b string) int {
	c := 0
	for i := 0; i < 4; i++ {
		if a[i] == b[i] {
			c++
		}
	}
	return c
}

func gao2(a, b string) int {
	c := 0
	for i := 0; i < 4; i++ {
		ch := a[i]
		found := false
		for j := 0; j < 4; j++ {
			if b[j] == ch {
				found = true
				break
			}
		}
		if found {
			c++
		}
	}
	return c
}

func main() {
	in := bufio.NewReader(os.Stdin)
	var n int
	fmt.Fscan(in, &n)

	x := make([]string, 0)
	for i := 100; i <= 9999; i++ {
		s := fmt.Sprintf("%04d", i)
		bytes := []byte(s)
		sort.Slice(bytes, func(i, j int) bool { return bytes[i] < bytes[j] })
		uniq := 1
		for j := 1; j < len(bytes); j++ {
			if bytes[j] != bytes[j-1] {
				uniq++
			}
		}
		if uniq >= 4 {
			x = append(x, s)
		}
	}

	for ; n > 0; n-- {
		var aInt, b, c int
		fmt.Fscan(in, &aInt, &b, &c)
		a := fmt.Sprintf("%04d", aInt)
		c += b

		nx := make([]string, 0, len(x))
		for _, s := range x {
			if gao1(s, a) == b && gao2(s, a) == c {
				nx = append(nx, s)
			}
		}
		x = nx
	}

	if len(x) == 0 {
		fmt.Println("Incorrect data")
	} else if len(x) > 1 {
		fmt.Println("Need more data")
	} else {
		fmt.Println(x[0])
	}
}

